package web

type documentationTopic struct {
	ID      string
	Title   string
	Intro   string
	Steps   []string
	Tips    []string
	Admin   bool
	Section string
}

func documentationTopics(lang string, admin, smtpEnabled bool) []documentationTopic {
	de := normalizeLanguage(lang) != "en"
	var topics []documentationTopic
	if de {
		topics = []documentationTopic{
			{ID: "start", Section: "Grundlagen", Title: "Erste Schritte", Intro: "Nach der Anmeldung findest du deine Kalender links im Bereich Kalender. Dein persönlicher Kalender gehört nur dir. Freigegebene Kalender erscheinen zusätzlich, sobald du Zugriff darauf bekommst.", Steps: []string{"Öffne Kalender, um zwischen deinen verfügbaren Kalendern zu wechseln.", "Erstelle Termine direkt im gewünschten Kalender.", "Öffne Kontoeinstellungen unten links für Sprache, Zeitzone, App-Passwörter und SSO."}},
			{ID: "personal-calendar", Section: "Kalender & Termine", Title: "Persönlicher Kalender", Intro: "Jeder Benutzer hat einen persönlichen Kalender. Er kann nicht geteilt oder gelöscht werden und ist nur für den jeweiligen Benutzer sichtbar.", Steps: []string{"Nutze ihn für deine eigenen Termine und Einladungen.", "Einladungen anderer ZentCal-Benutzer erscheinen dort automatisch."}},
			{ID: "shared-calendars", Section: "Kalender & Termine", Title: "Freigegebene Kalender", Intro: "Freigegebene Kalender sind für Teams oder gemeinsame Termine gedacht. Welche Aktionen möglich sind, hängt von deiner Rolle im Kalender ab.", Steps: []string{"Betrachter können Termine nur ansehen.", "Bearbeiten darf Termine anlegen, ändern und löschen.", "Eigentümer dürfen zusätzlich Benutzer des Kalenders verwalten.", "Modus Normal: Benutzer mit Bearbeitungsrechten arbeiten gemeinsam an den Terminen des Kalenders.", "Modus Personal: Jeder Benutzer kann nur die von ihm selbst erstellten Termine ändern oder löschen."}},
			{ID: "events", Section: "Kalender & Termine", Title: "Termine und Einladungen", Intro: "Beim Erstellen eines Termins kannst du Teilnehmer per E-Mail einladen. ZentCal erkennt automatisch, ob die Adresse zu einem lokalen Benutzer gehört.", Steps: []string{"Lokale Benutzer erhalten die Einladung in ZentCal und, wenn SMTP eingerichtet ist, zusätzlich per E-Mail.", "Externe Teilnehmer erhalten eine normale Kalendereinladung per E-Mail.", "Bei relevanten Terminänderungen informiert ZentCal die Teilnehmer und nennt in der Mail die geänderten Bereiche. Reine technische oder unveränderte Speicherungen lösen keine Update-Mail aus.", "Einladungen können angenommen, vorläufig angenommen oder abgelehnt werden."}},
			{ID: "devices", Section: "Konto & Geräte", Title: "CalDAV und App-Passwörter", Intro: "Für Kalender-Apps und DAV-Clients verwendest du ein App-Passwort. Dein normales ZentCal-Passwort ist dafür nicht gedacht.", Steps: []string{"Öffne API & Geräte, um die CalDAV-Verbindungsdaten für dein Gerät zu sehen.", "Öffne dort über App-Passwörter deine Kontoeinstellungen und erstelle ein eigenes App-Passwort für das Gerät.", "Kopiere das Passwort direkt. Es wird nur einmal angezeigt.", "Trage die angezeigten CalDAV-Daten zusammen mit diesem App-Passwort in deiner Kalender-App ein."}, Tips: []string{"Wenn ein Gerät verloren geht, widerrufe nur dessen App-Passwort. Andere Geräte bleiben verbunden."}},
			{ID: "sso-account", Section: "Konto & Geräte", Title: "Konto mit SSO verbinden", Intro: "Wenn Single Sign-On eingerichtet ist, kannst du dein bestehendes ZentCal-Konto bewusst mit deinem Konto beim Identity Provider verbinden.", Steps: []string{"Öffne die Kontoeinstellungen.", "Wähle Mit SSO verbinden und bestätige zuerst dein aktuelles ZentCal-Passwort.", "Melde dich danach beim Identity Provider an. Nach erfolgreicher Verknüpfung läuft die Anmeldung über SSO; das lokale Passwort wird für den Login deaktiviert."}, Tips: []string{"App-Passwörter bleiben auch bei SSO erhalten.", "Beim Trennen der SSO-Verbindung wird ein temporäres lokales Passwort per E-Mail verschickt."}},
			{ID: "account", Section: "Konto & Geräte", Title: "Kontoeinstellungen", Intro: "Sprache und Zeitzone kannst du selbst ändern. Name und E-Mail-Adresse werden durch einen Administrator oder den Identity Provider verwaltet.", Steps: []string{"Öffne unten links dein Benutzerkonto.", "Passe Sprache oder Zeitzone an und speichere.", "Lokale Benutzer können dort auch ihr Passwort ändern."}},
			{ID: "admin-users", Section: "Administration", Title: "Benutzer verwalten", Intro: "Unter Benutzer legst du Konten an, bearbeitest bestehende Benutzer und steuerst deren Rolle und Status.", Steps: []string{"Lege Vorname, Nachname und E-Mail-Adresse fest.", "Lege mit Eigene Kalender erstellen fest, ob der Benutzer zusätzliche Kalender anlegen darf.", "Nutze Owner oder Administrator nur für Personen, die ZentCal verwalten sollen.", "Für lokale Benutzer kann ein temporäres Passwort erzeugt werden.", "Beim Löschen eines Benutzers entscheidet der Administrator, ob allein von ihm verwaltete Kalender übertragen oder mitgelöscht werden. Der letzte aktive Owner kann nicht gelöscht werden."}, Admin: true},
			{ID: "admin-calendars", Section: "Administration", Title: "Kalender verwalten", Intro: "Die Kalenderverwaltung ist für zentral verwaltete gemeinsame Kalender gedacht, zum Beispiel für Abteilungen. Benutzer selbst erstellte Kalender bleiben außerhalb dieser Verwaltung.", Steps: []string{"Erstelle einen zentralen Kalender und füge die benötigten Benutzer mit Eigentümer-, Bearbeiten- oder Betrachter-Rolle hinzu.", "Der administrative Verwalter erhält dadurch keinen Zugriff auf Termine oder Teilnehmer.", "Mit „In meinen Kalendern anzeigen“ kann der Verwalter den Kalender bei Bedarf zusätzlich schreibgeschützt als Betrachter einblenden.", "Wird der letzte Eigentümer entfernt oder gelöscht, bleibt der Kalender vorübergehend administrativ verwaltbar, bis ein neuer Eigentümer gesetzt wird."}, Admin: true},
			{ID: "admin-sso", Section: "Administration", Title: "Single Sign-On einrichten", Intro: "SSO wird unter Einstellungen konfiguriert. ZentCal zeigt dort auch die Redirect URI an, die beim Provider hinterlegt werden muss.", Steps: []string{"Trage Issuer, Client-ID und Client-Secret ein.", "Hinterlege die angezeigte Redirect URI beim Provider.", "Teste die Verbindung, bevor du den lokalen Login deaktivierst.", "Auto-Provisioning wirkt nur über den direkten SSO-Link und nur, wenn es aktiviert ist."}, Tips: []string{"Vor- und Nachname werden nur beim Auto-Provisioning eines neuen Kontos übernommen. E-Mail und Rollen werden nur synchronisiert, wenn der jeweilige Schalter aktiviert ist."}, Admin: true},
			{ID: "admin-mail", Section: "Administration", Title: "SMTP und E-Mail-Vorlagen", Intro: "SMTP wird für Einladungen, Passwort-Mails und andere Benachrichtigungen verwendet. Die Texte kannst du in den E-Mail-Vorlagen anpassen.", Steps: []string{"Richte SMTP unter Einstellungen ein und sende zuerst eine Testmail.", "Bearbeite Betreff und Inhalt der gewünschten Vorlage.", "Optional kannst du ein gemeinsames HTML-Layout aktivieren und {{email_template}} als Platzhalter für den eigentlichen Inhalt verwenden."}, Tips: []string{"Ohne HTML-Layout wird weiterhin eine normale Textmail verschickt. Mit aktiviertem Layout sendet ZentCal Text und HTML gemeinsam."}, Admin: true},
			{ID: "admin-mail-deliveries", Section: "Administration", Title: "E-Mail-Zustellungen", Intro: "Unter E-Mail-Zustellungen siehst du, ob ZentCal E-Mails erfolgreich an den SMTP-Server übergeben konnte.", Steps: []string{"Filtere bei Bedarf nach Status oder Mailtyp.", "Bei einem Fehler zeigt ZentCal eine kurze technische Ursache an.", "Einträge werden nach 30 Tagen automatisch gelöscht."}, Tips: []string{"ZentCal speichert dort keine Mailinhalte und keine vollständigen externen Empfängeradressen."}, Admin: true},
			{ID: "admin-webhooks", Section: "Administration", Title: "Webhooks", Intro: "Webhooks informieren andere Systeme über Ereignisse in ZentCal. Du entscheidest pro Webhook, welche Ereignisse übertragen werden.", Steps: []string{"Lege Ziel-URL und gewünschte Ereignisse fest.", "Bewahre das Secret sicher auf; es wird zur Prüfung der Webhook-Signatur verwendet.", "Nutze die Testfunktion, bevor du den Webhook produktiv verwendest.", "Für Backups stehen Erfolgs-, Fehler-, Verify- und Restore-Ereignisse zur Verfügung. E-Mail-Fehler können über email.failed gemeldet werden."}, Admin: true},
			{ID: "admin-api", Section: "Administration", Title: "Admin API", Intro: "Die Admin API ist für Automatisierung und externe Verwaltung gedacht. Sie verwendet eigene Admin-API-Tokens und ist von normalen Benutzer-Tokens getrennt.", Steps: []string{"Erstelle unter Admin API einen Token mit nur den benötigten Berechtigungen.", "Nutze die integrierte API-Dokumentation für Payloads, cURL-Beispiele und Antworten.", "Mit dem Playground kannst du Requests direkt gegen deine eigene ZentCal-Instanz testen."}, Tips: []string{"Restore-Berechtigungen sind bewusst separat und sollten nur vergeben werden, wenn sie wirklich benötigt werden."}, Admin: true},
			{ID: "admin-backups", Section: "Administration", Title: "Backups und Wiederherstellung", Intro: "Backups sichern die ZentCal-Datenbank und die für einen Restore nötigen Daten. Je nach Einrichtung können sie lokal oder auf einem externen Ziel abgelegt werden.", Steps: []string{"Konfiguriere zuerst das Backup-Ziel und teste die Verbindung.", "Lege ein Backup-Verschlüsselungspasswort fest. Ohne dieses Passwort können weder manuelle noch automatische Backups erstellt werden.", "Bei SFTP wählst du entweder Passwort oder SSH Private Key als Anmeldung.", "Bei einem manuellen Backup zeigt ZentCal den aktuellen Arbeitsschritt an.", "Vor einer Wiederherstellung sollte ein aktuelles Backup vorhanden sein."}, Tips: []string{"Eine Wiederherstellung überschreibt den aktuellen Datenstand. Lokale Admins bestätigen sie mit ihrem aktuellen Passwort, SSO-Admins melden sich dafür erneut beim Identity Provider an."}, Admin: true},
			{ID: "admin-system", Section: "Administration", Title: "System und Updates", Intro: "Unter System findest du Statusinformationen zur laufenden ZentCal-Instanz. Updates sollten immer zusammen mit einem aktuellen Backup eingespielt werden.", Steps: []string{"Prüfe vor einem Update, ob ein aktuelles Backup vorhanden ist.", "Spiele anschließend die neue ZentCal-Version ein.", "Kontrolliere nach dem Start kurz Systemstatus, Anmeldung und Kalenderzugriff."}, Admin: true},
		}
	} else {
		topics = []documentationTopic{
			{ID: "start", Section: "Basics", Title: "Getting started", Intro: "After signing in, your calendars are available under Calendars. Your personal calendar belongs only to you. Shared calendars appear as soon as access is granted.", Steps: []string{"Open Calendars to switch between the calendars available to you.", "Create events directly in the calendar you want to use.", "Open Account settings at the bottom left for language, timezone, app passwords and SSO."}},
			{ID: "personal-calendar", Section: "Calendars & events", Title: "Personal calendar", Intro: "Every user has one personal calendar. It cannot be shared or deleted and is only visible to that user.", Steps: []string{"Use it for your own events and invitations.", "Invitations from other ZentCal users appear there automatically."}},
			{ID: "shared-calendars", Section: "Calendars & events", Title: "Shared calendars", Intro: "Shared calendars are intended for teams or shared schedules. What you can do depends on your role in the calendar.", Steps: []string{"Viewers can only read events.", "Contributors can create, change and delete events.", "Owners can also manage calendar members.", "Normal mode: users with edit permissions work on the calendar events together.", "Personal mode: each user can only change or delete events they created themselves."}},
			{ID: "events", Section: "Calendars & events", Title: "Events and invitations", Intro: "When creating an event you can invite participants by email. ZentCal automatically detects whether the address belongs to a local user.", Steps: []string{"Local users receive the invitation in ZentCal and, when SMTP is configured, by email as well.", "External participants receive a regular calendar invitation by email.", "For relevant event changes, ZentCal informs participants and lists the changed areas in the email. Purely technical or unchanged saves do not send an update email.", "Invitations can be accepted, tentatively accepted or declined."}},
			{ID: "devices", Section: "Account & devices", Title: "CalDAV and app passwords", Intro: "Calendar apps and DAV clients use an app password. Your regular ZentCal password is not intended for this.", Steps: []string{"Open API & Devices to view the CalDAV connection details for your device.", "Use App passwords there to open your account settings and create a separate app password for the device.", "Copy the password immediately. It is shown only once.", "Enter the displayed CalDAV details together with that app password in your calendar app."}, Tips: []string{"If a device is lost, revoke only its app password. Other devices stay connected."}},
			{ID: "sso-account", Section: "Account & devices", Title: "Connect your account to SSO", Intro: "When Single Sign-On is configured, you can deliberately connect your existing ZentCal account to your identity provider account.", Steps: []string{"Open Account settings.", "Choose Connect with SSO and first confirm your current ZentCal password.", "Then sign in at the identity provider. After linking, sign-in uses SSO and the local password is disabled for login."}, Tips: []string{"App passwords remain valid with SSO.", "When SSO is disconnected, a temporary local password is sent by email."}},
			{ID: "account", Section: "Account & devices", Title: "Account settings", Intro: "You can change language and timezone yourself. Name and email address are managed by an administrator or the identity provider.", Steps: []string{"Open your account at the bottom left.", "Change language or timezone and save.", "Local users can also change their password there."}},
			{ID: "admin-users", Section: "Administration", Title: "Manage users", Intro: "Under Users you create accounts, edit existing users and control their role and status.", Steps: []string{"Set first name, last name and email address.", "Use Create own calendars to control whether the user may create additional calendars.", "Use Owner or Administrator only for people who should manage ZentCal.", "A temporary password can be generated for local users.", "When deleting a user, the administrator decides whether calendars owned only by that user are transferred or deleted as well. The last active Owner cannot be deleted."}, Admin: true},
			{ID: "admin-calendars", Section: "Administration", Title: "Manage calendars", Intro: "Calendar management is for centrally managed shared calendars, for example department calendars. Calendars created by users themselves stay outside this administration view.", Steps: []string{"Create a centrally managed calendar and add the required users as Owner, Contributor or Viewer.", "The administrative manager does not gain access to events or participants.", "Use “Show in my calendars” to optionally add the calendar to the manager’s own calendar list as a read-only viewer.", "If the last Owner is removed or deleted, the calendar remains administratively manageable until a new Owner is assigned."}, Admin: true},
			{ID: "admin-sso", Section: "Administration", Title: "Set up Single Sign-On", Intro: "SSO is configured under Settings. ZentCal also shows the redirect URI that must be registered with the provider.", Steps: []string{"Enter issuer, client ID and client secret.", "Register the displayed redirect URI at the provider.", "Test the connection before disabling local login.", "Auto-provisioning only applies to the direct SSO link and only when enabled."}, Tips: []string{"First and last name are imported only when a new account is auto-provisioned. Email and roles are synchronized only when the matching option is enabled."}, Admin: true},
			{ID: "admin-mail", Section: "Administration", Title: "SMTP and email templates", Intro: "SMTP is used for invitations, password emails and other notifications. The text can be customized in Email templates.", Steps: []string{"Configure SMTP under Settings and send a test email first.", "Edit subject and content of the template you need.", "Optionally enable a shared HTML layout and place {{email_template}} where the message content should appear."}, Tips: []string{"Without an HTML layout ZentCal still sends a normal text email. With HTML enabled, text and HTML are sent together."}, Admin: true},
			{ID: "admin-mail-deliveries", Section: "Administration", Title: "Email deliveries", Intro: "Email deliveries shows whether ZentCal successfully handed messages to the SMTP server.", Steps: []string{"Filter by status or message type when needed.", "For failed deliveries ZentCal shows a short technical reason.", "Entries are automatically deleted after 30 days."}, Tips: []string{"ZentCal stores neither message content nor complete external recipient addresses in this history."}, Admin: true},
			{ID: "admin-webhooks", Section: "Administration", Title: "Webhooks", Intro: "Webhooks notify other systems about events in ZentCal. You choose which events are sent for each webhook.", Steps: []string{"Set the destination URL and desired events.", "Keep the secret safe; it is used to verify webhook signatures.", "Use the test action before relying on the webhook in production.", "Backup success/failure, verify/restore errors and email.failed can also be sent as webhook events."}, Admin: true},
			{ID: "admin-api", Section: "Administration", Title: "Admin API", Intro: "The Admin API is intended for automation and external administration. It uses separate admin API tokens and is independent from regular user tokens.", Steps: []string{"Create a token under Admin API with only the permissions you need.", "Use the built-in API documentation for payloads, cURL examples and responses.", "The playground can send test requests directly to your own ZentCal instance."}, Tips: []string{"Restore permission is separate on purpose and should only be granted when it is truly needed."}, Admin: true},
			{ID: "admin-backups", Section: "Administration", Title: "Backups and restore", Intro: "Backups protect the ZentCal database and the data required for recovery. Depending on your setup they can be stored locally or on an external destination.", Steps: []string{"Configure the backup destination and test the connection first.", "Set a backup encryption password. Manual and automatic backups cannot run without it.", "For SFTP, choose either password or SSH private key authentication.", "For a manual backup, ZentCal shows the current processing step.", "Before restoring, make sure a current backup exists."}, Tips: []string{"A restore replaces the current data state. Local admins confirm it with their current password; SSO admins reauthenticate with the identity provider."}, Admin: true},
			{ID: "admin-system", Section: "Administration", Title: "System and updates", Intro: "System shows status information about the running ZentCal instance. Updates should always be installed together with a current backup.", Steps: []string{"Check that a current backup exists before updating.", "Install the new ZentCal version.", "After startup, briefly verify system status, sign-in and calendar access."}, Admin: true},
		}
	}
	if !admin && !smtpEnabled {
		for i := range topics {
			if topics[i].ID != "events" {
				continue
			}
			if de {
				topics[i].Intro = "Beim Erstellen eines Termins erkennt ZentCal automatisch, ob ein Teilnehmer zu einem lokalen Benutzer gehört."
				topics[i].Steps = []string{
					"Lokale Benutzer erhalten die Einladung direkt in ZentCal.",
					"Einladungen können angenommen, vorläufig angenommen oder abgelehnt werden.",
				}
			} else {
				topics[i].Intro = "When creating an event, ZentCal automatically detects whether a participant belongs to a local user."
				topics[i].Steps = []string{
					"Local users receive the invitation directly in ZentCal.",
					"Invitations can be accepted, tentatively accepted or declined.",
				}
			}
		}
	}
	if admin {
		return topics
	}
	out := topics[:0]
	for _, topic := range topics {
		if !topic.Admin {
			out = append(out, topic)
		}
	}
	return out
}

func documentationSections(topics []documentationTopic) []string {
	seen := map[string]bool{}
	out := make([]string, 0, 4)
	for _, topic := range topics {
		if !seen[topic.Section] {
			seen[topic.Section] = true
			out = append(out, topic.Section)
		}
	}
	return out
}
